package cart

import "errors"

var ErrInvalidLine = errors.New("invalid cart line")

type Line struct {
    UnitPriceCents int64
    Quantity int64
}

func Total(lines []Line) (int64, error) {
    var total int64
    for _, line := range lines {
        if line.UnitPriceCents < 0 || line.Quantity < 0 {
            return 0, ErrInvalidLine
        }
        total += line.UnitPriceCents * line.Quantity
    }
    return total, nil
}

