package cart

import (
    "errors"
    "testing"
)

func TestTotal(t *testing.T) {
    total, err := Total([]Line{{UnitPriceCents: 199, Quantity: 2}, {UnitPriceCents: 50, Quantity: 1}})
    if err != nil || total != 448 { t.Fatalf("total=%d err=%v", total, err) }
}

func TestRejectsNegativeValues(t *testing.T) {
    for _, line := range []Line{{UnitPriceCents: -1, Quantity: 1}, {UnitPriceCents: 10, Quantity: -1}} {
        if _, err := Total([]Line{line}); !errors.Is(err, ErrInvalidLine) { t.Fatalf("line=%+v err=%v", line, err) }
    }
}
